begin;

do $$
declare
  native_count integer;
begin
  select count(*)
    into native_count
  from public.calendar_days
  where country_code = 'BG'
    and calendar_code = 'bg-bulgarian-patriarchate'
    and language_code = 'bg'
    and calendar_date between date '2026-01-01' and date '2026-12-31';

  if native_count <> 365 then
    raise exception 'Expected 365 native BG rows; found %', native_count;
  end if;
end
$$;

